$('kitchenButton').onclick=openFoodKitchen;$('foodPouch').onclick=openFarm;$('sell').onclick=goBank;$('warehouse').onclick=goWarehouse;$('zoomIn').onclick=()=>scene?.setZoom(.1);$('zoomOut').onclick=()=>scene?.setZoom(-.1);
