  if(simDt&&atBank&&state.bag>0){if(!isSelling){isSelling=true;saleRate=Math.max(28,state.bag/1.3);saleCarry=0;saleTotal=0;saleClock=0;}saleCarry+=dt*saleRate;saleClock+=dt;if(saleCarry>=2||state.bag<=saleCarry){const result=unload(state,Math.min(state.bag,Math.floor(saleCarry)));saleCarry-=result.units;saleTotal+=result.value;scene.receiveMoney(player,result.value);if(saleClock>.13){scene.makeSale(player);sound('sale');saleClock=0;}if(!state.bag){floater(WORLD.bank.x,WORLD.bank.z,'+ '+format(saleTotal)+' ✧');if(state.tutorial<3){tutorial(3);toast('Ernte verkauft. Kaufe Verbesserungen, indem du auf den ↑-Flächen stehen bleibst.');}save();}}}else{isSelling=false;saleCarry=0;}
  productSaleClock+=simDt;if(simDt&&atBank&&productSaleClock>.7){productSaleClock=0;const batch=sellCarriedProducts(state);if(batch.count){scene.receiveMoney(player,batch.value);floater(WORLD.bank.x,WORLD.bank.z,'Produkte + '+format(batch.value)+' ✧');sound('sale');scene.makeSale(player);}}
  if(simDt&&atWarehouse&&collectingRaw){const batch=withdrawBag(state,capacity(state)-state.bag-productCargoCount(state));collectingRaw=false;if(batch.count)goBank();else toast('Keine Rohstoffe zum Abholen.');}else if(simDt&&atWarehouse&&!player.moving&&state.bag>0){const batch=depositBag(state,Math.max(1,Math.floor(dt*90)));if(batch.count){scene.makeTransfer(player,VILLAGE.warehouse);if(state.tutorial<3)tutorial(3);}else if(!storageWarned){toast('Das Lager ist voll. Verarbeite Vorräte oder vergrößere den Lagerschuppen.');storageWarned=true;}}else storageWarned=false;
  if(!atWarehouse)foodWarehouseHold=false;
  if(simDt&&atWarehouse&&!player.moving&&!foodWarehouseHold&&state.village.farm.food){storeSnailFood(state);scene.makeFoodFlight(player,VILLAGE.warehouse);save();}
